slot_0_1_0 = draw.shader("cbuffer cb : register(b0) {\n    float4x4 mvp; // Model-View-Projection matrix\n    float2 tex;   // Texture dimensions (not used in this case)\n    float time;   // Time variable for animation\n    float alpha;  // Alpha value for transparency\n};\n\nstruct PS_INPUT {\n    float4 pos : SV_POSITION; // Position of the vertex\n    float4 col : COLOR0;      // Color of the vertex\n    float2 uv : TEXCOORD0;    // UV coordinates\n};\n\nfloat4 main(PS_INPUT input) : SV_Target {\n    float waveFrequency = 7.5 + 1.5 * sin(time * 2); // Frequency of the waves\n    float waveAmplitude = 3.5 + cos(time + 2) * 0.25;   // Base amplitude of the waves\n    float waveSpeed = 3.0;       // Speed of the wave movement\n\n    float wave = sin(input.uv.x * waveFrequency + time * waveSpeed);\n\n    float amplitudeFactor = abs(sin(input.uv.x * 3.1415)); // Decrease amplitude towards the left\n    float finalWave = wave * waveAmplitude * amplitudeFactor * abs(cos(time * 0.0125));\n\n    float height = input.uv.y - finalWave;\n\n    float4 color;\n    if ((height < 1 && height > -0.05)) {\n        color = float4(input.col.rgb, sin(input.uv.x * 3.1415) * 0.2 * input.col.a); // White color for the wave\n    } else {\n        color = float4(0.0, 0.0, 0.0, 0.0); // Transparent color\n    }\n\n    return color;\n}\n")
slot_0_2_0 = draw.shader("cbuffer cb : register(b0) {\n    float4x4 mvp; // Model-View-Projection matrix\n    float2 tex;   // Texture dimensions (not used in this case)\n    float time;   // Time variable for animation\n    float alpha;  // Alpha value for transparency\n};\n\nstruct PS_INPUT {\n    float4 pos : SV_POSITION; // Position of the vertex\n    float4 col : COLOR0;      // Color of the vertex\n    float2 uv : TEXCOORD0;    // UV coordinates\n};\n\n\n// use texture sampler and texture.\nsampler sampler0;\nTexture2D texture0;\n\nfloat4 main(PS_INPUT input) : SV_Target {\n    float4 color = texture0.Sample(sampler0, input.uv);\n\n    if (color.a > 0.6) {\n\treturn lerp(input.col, float4(1, 1, 1, 1), input.uv.y);\n    }\n\n    return float4(0, 0, 0, 0);\n}\n")
slot_0_3_0 = draw.shader("// define constant buffer.\ncbuffer cb : register(b0) {\n    float4x4 mvp;\n    float2 tex;\n    float time;\n    float alpha;\n};\n\n// define input.\nstruct PS_INPUT {\n    float4 pos : SV_POSITION;\n    float4 col : COLOR0;\n    float2 uv : TEXCOORD0;\n};\n\n// use texture sampler and texture.\nsampler sampler0;\nTexture2D texture0;\n\nfloat4 main(PS_INPUT inp) : SV_Target {\n    float radius = 2; // blur radius\n    float2 inv_size = 1.0 / tex.xy; // inversed size of the texture\n    float weight = 0.0; // total weight\n    float4 color = 0.0; // total color\n\n    // perform a gaussian blur\n    for (float x = -radius; x <= radius; x += 1.0)\n    {\n        for (float y = -radius; y <= radius; y += 1.0)\n        {\n            float2 coord = inp.uv + float2(x, y) * inv_size;\n            color += texture0.Sample(sampler0, coord) * exp(-((x * x + y * y) / (2.0 * radius * radius)));\n            weight += exp(-((x * x + y * y) / (2.0 * radius * radius)));\n        }\n    }\n\n    // average the color\n    color /= weight;\n\tcolor.a = inp.col.a;\n    return color;\n}\n")
